return [{ json: {
  supabase: {
    url: "https://mdnthwpcnphjnnblbvxk.supabase.co",
    serviceKey: "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im1kbnRod3BjbnBoam5uYmxidnhrIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2MDUwMDc4MCwiZXhwIjoyMDc2MDc2NzgwfQ.wNVQ3U2nWTGu8VsuXKasWOCxVhpca5x42wSapQDinGs"
  },
  r2: {
    bucket: "little-hero-orders",
    signedUrlEndpoint: "https://admin.littleherolabs.com/api/r2/signed-url",
    apiToken: "e41d510ce6ed6e9c7f602fea860f2591cc7ec75fe63e448336a97c4b73898646",
    expiresIn: 600,
    keyPrefix: "book-mvp-simple-adventure/orders",
    useBackendSignedUpload: true  // set false to use S3 node instead
  },
  s3: {
    endpoint: "https://3daae940fcb6fc5b8bbd9bb8fcc62854.r2.cloudflarestorage.com",
    accessKeyId: "b0a481f17d8641a232e0aae8a3efeb7a",
    secretAccessKey: "745ade64f37a8def63e44ae9bfb2fb286c23a500b437c722461a33c7820d43cd",
    accountId: "3daae940fcb6fc5b8bbd9bb8fcc62854"
  }
} }];

// Accepts many shapes (Amazon Custom / backend forwarder / mock)
// Normalize core fields and optional specs. Dedication is handled in the next node.
// Gets CONFIG from earlier node execution (CONFIG runs before Mock Order)
const raw = $input.first().json || {};
const config = $item(0).$node["CONFIG (PRODUCTION)"]?.json || {};

function safe(o){ return (o && typeof o === 'object') ? o : {}; }
function coerceStr(v){ return (v==null) ? undefined : String(v); }
function num(v){ const n = Number(v); return Number.isFinite(n) ? n : undefined; }
function extractItems(r){ return Array.isArray(r.items) ? r.items : (Array.isArray(r.lineItems) ? r.lineItems : []); }
function extractOrderId(r){ return r.amazonOrderId || r.orderId || r.id || 'UNKNOWN-ORDER'; }

const orderId = extractOrderId(raw);
const items = extractItems(raw);

// Optional specs
const cs = safe(raw.characterSpecs);
const bs = safe(raw.bookSpecs);
const od = safe(raw.orderDetails);
const shipping = safe(od.shippingAddress);

const characterSpecs = {
  childName: coerceStr(cs.childName),
  skinTone: coerceStr(cs.skinTone),
  hairColor: coerceStr(cs.hairColor),
  hairStyle: coerceStr(cs.hairStyle),
  age: num(cs.age),
  pronouns: coerceStr(cs.pronouns),
  favoriteColor: coerceStr(cs.favoriteColor),
  animalGuide: coerceStr(cs.animalGuide),
  clothingStyle: coerceStr(cs.clothingStyle),
};

const bookSpecs = {
  title: coerceStr(bs.title),
  totalPages: num(bs.totalPages),
  format: coerceStr(bs.format),
  bookType: coerceStr(bs.bookType),
};

const orderDetails = {
  quantity: num(od.quantity) || 1,
  shippingAddress: {
    name: coerceStr(shipping.name),
    address: coerceStr(shipping.address),
    city: coerceStr(shipping.city),
    state: coerceStr(shipping.state),
    zip: coerceStr(shipping.zip),
    phone: coerceStr(shipping.phone || shipping.phoneNumber || shipping.phone_number), // CRITICAL: Required for Lulu API
  }
};

return [{
  json: {
    _raw: raw,
    _config: config, // Merge config into flow for downstream nodes
    orderId,
    // legacy fields for compatibility
    buyer: raw.buyer || {},
    purchaseDate: raw.purchaseDate || raw.createdAt || null,
    // normalized fields
    status: coerceStr(raw.status) || 'queued_for_processing',
    orderDate: coerceStr(raw.orderDate) || new Date().toISOString(),
    customerEmail: coerceStr(raw.customerEmail),
    items,
    characterSpecs,
    bookSpecs,
    orderDetails
  }
}];

// Extract & sanitize dedication from normalized shape
const norm = $input.first().json || {};

function fromItem(it){
  const fields = it.customizations || it.customizationFields || it.options || [];
  for (const f of (fields||[])){
    const name = (f.name||f.label||f.type||'').toLowerCase();
    if (name.includes('dedication') || name.includes('message') || name.includes('note')){
      const v = (f.value||f.text||f.stringValue||'')+'';
      if (v.trim()) return v;
    }
  }
  return null;
}

let found = '';
if (norm._raw?.dedication) found = String(norm._raw.dedication);
if (!found && Array.isArray(norm.items)) {
  for (const li of norm.items){
    const maybe = fromItem(li);
    if (maybe){ found = maybe; break; }
  }
}

// sanitize
const MAX_CHARS = 500, MAX_LINES = 6;
let t = (found || '')
  .replace(/[\u0000-\u0008\u000B-\u001F\u007F]/g,'')
  .replace(/\r\n?/g,'\n').replace(/[ \t]{2,}/g,' ');
t = t.split('\n').map(l => l.trimEnd()).join('\n').trim();
if (t.length > MAX_CHARS) t = t.slice(0, MAX_CHARS).trim();
t = t.split('\n').slice(0, MAX_LINES).join('\n');
const esc = s => s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

return [{
  json: {
    ...norm,
    dedication: { raw: found || '', text: t, htmlSafe: esc(t) }
  }
}];

// Build 1‑manifest.json with normalized fields
const j = $input.first().json;
const r2Key = `book-mvp-simple-adventure/orders/${j.orderId}/manifests/1-manifest.json`;

// Extract marketplaceId from raw input or normalized fields
const marketplaceId = j._raw?.marketplaceId || j.marketplaceId || null;

const manifest = {
  schema: "lhb.run-manifest@v2.1",
  runStamp: new Date().toISOString(),
  amazonOrderId: j.orderId,
  marketplaceId: marketplaceId, // Include marketplaceId for Supabase upsert
  order: {
    purchaseDate: j.orderDate || j.purchaseDate || null,
    buyer: { email: j.customerEmail, ...j.buyer },
    dedication: j.dedication,
    characterSpecs: j.characterSpecs,
    bookSpecs: j.bookSpecs,
    orderDetails: {
      ...j.orderDetails,
      shippingAddress: {
        ...j.orderDetails.shippingAddress,
        phone: j.orderDetails.shippingAddress?.phone // Ensure phone is preserved in manifest
      }
    }
  }
};

return [{ json: { manifest, r2Key, orderId: j.orderId } }];

// Build fallback (no upload): get manifest/r2Key from Build node or input
const input = $input.first().json || {};
const buildNode = $item(0).$node["Build 1‑manifest.json"]?.json;
const manifest = input.manifest || buildNode?.manifest;
const r2Key = input.r2Key || buildNode?.r2Key;
const _config = input._config || $item(0).$node["Normalize Payload"]?.json?._config || {};
return [{ json: { r2Key, manifest, _config } }];

// Upsert into Supabase orders with ALL fields from manifest
// Get config and current input (works from both R2 upload path and fallback path)
const input = $input.first().json || {};
const cfg = input._config || $item(0).$node["CONFIG (PRODUCTION)"]?.json || {};

// Get manifest and r2Key - try current input first, then fallback to Build node
const buildNode = $item(0).$node["Build 1‑manifest.json"]?.json;
const manifest = input.manifest || buildNode?.manifest;
const r2Key = input.r2Key || buildNode?.r2Key;

console.log('=== SUPABASE UPSERT DEBUG ===');
console.log('Input keys:', Object.keys(input));
console.log('Has manifest:', !!manifest);
console.log('Has r2Key:', !!r2Key);
console.log('Has config:', !!cfg.supabase);

if (!manifest || !manifest.amazonOrderId) {
  throw new Error('Missing manifest or amazonOrderId. Input: ' + JSON.stringify(Object.keys(input)) + ', Build: ' + JSON.stringify(buildNode ? Object.keys(buildNode) : 'null'));
}

if (!r2Key) {
  throw new Error('Missing r2Key. Input: ' + JSON.stringify(Object.keys(input)) + ', Build: ' + JSON.stringify(buildNode ? Object.keys(buildNode) : 'null'));
}

if (!cfg.supabase || !cfg.supabase.url || !cfg.supabase.serviceKey) {
  throw new Error('Missing Supabase config. Config keys: ' + JSON.stringify(Object.keys(cfg)));
}

// Generate character hash from characterSpecs if available
function generateCharacterHash(specs) {
  if (!specs || !specs.childName) return null;
  const hashInput = `${specs.childName}-${specs.skinTone}-${specs.hairColor}-${specs.hairStyle}`;
  let hash = 0;
  for (let i = 0; i < hashInput.length; i++) {
    const char = hashInput.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32-bit integer
  }
  return Math.abs(hash).toString(16).slice(0, 16);
}

const order = manifest.order || {};
const characterSpecs = order.characterSpecs || null;
const characterHash = characterSpecs ? generateCharacterHash(characterSpecs) : null;

// Build complete body with all fields
const body = {
  orderId: manifest.amazonOrderId,        // Required: NOT NULL constraint
  amazon_order_id: manifest.amazonOrderId,
  execution_status: 'ready_for_processing',
  next_workflow: '2A',                 // queue 2A first (character creation)
  one_manifest_url: r2Key,             // store the KEY (durable)
  dedication_text: order.dedication?.text || null,
  // queued_at is NOT set here - router cron will set it when picking up the order

  // Add all missing fields from manifest
  character_specs: characterSpecs,
  character_hash: characterHash,
  customer_email: order.buyer?.email || null,
  customer_name: order.buyer?.name || null,
  shipping_address: order.orderDetails?.shippingAddress || null,
  product_info: order.orderDetails || null,
  purchase_date: order.purchaseDate || null,
  workflow_step: 'order_intake',
  status: 'queued_for_processing',
  marketplace_id: manifest.marketplaceId || null
};

console.log('Request body:', JSON.stringify(body, null, 2));
console.log('Request URL:', `${cfg.supabase.url}/rest/v1/orders`);

// Try PATCH first (update if exists), then POST if not found
const headers = {
  'apikey': cfg.supabase.serviceKey,
  'Authorization': `Bearer ${cfg.supabase.serviceKey}`,
  'Prefer': 'return=representation',
  'Content-Type': 'application/json'
};

try {
  // First, try to PATCH (update existing record)
  const patchRes = await this.helpers.request({
    method: 'PATCH',
    uri: `${cfg.supabase.url}/rest/v1/orders?amazon_order_id=eq.${encodeURIComponent(body.amazon_order_id)}`,
    headers: headers,
    body: JSON.stringify(body)
  });

  // Parse response if it's a string (Supabase sometimes returns JSON strings)
  const patchParsed = typeof patchRes === 'string' ? JSON.parse(patchRes) : patchRes;
  // Supabase REST API returns arrays - check if we got a result
  const patchData = Array.isArray(patchParsed) ? patchParsed[0] : patchParsed;
  if (patchData && typeof patchData === 'object' && Object.keys(patchData).length > 0) {
    console.log('✅ Supabase PATCH successful (record updated)');
    return [{ json: patchData }];
  }

  // If no data returned, record doesn't exist - try POST
  console.log('Record not found, trying POST insert...');
  try {
    const postRes = await this.helpers.request({
      method: 'POST',
      uri: `${cfg.supabase.url}/rest/v1/orders`,
      headers: headers,
      body: JSON.stringify(body)
    });

    // Parse response if it's a string (Supabase sometimes returns JSON strings)
    const postParsed = typeof postRes === 'string' ? JSON.parse(postRes) : postRes;
    // Supabase REST API returns arrays - extract first element
    const postData = Array.isArray(postParsed) ? postParsed[0] : postParsed;
    if (!postData || typeof postData !== 'object') {
      throw new Error('Invalid response from Supabase POST: ' + JSON.stringify(postRes));
    }

    console.log('✅ Supabase POST successful (record inserted)');
    return [{ json: postData }];
  } catch (postError) {
    console.error('❌ POST failed, error details:');
    console.error('Error message:', postError.message);
    if (postError.response) {
      console.error('POST Response status:', postError.response.status);
      console.error('POST Response data:', JSON.stringify(postError.response.data, null, 2));
      console.error('POST Request body:', JSON.stringify(body, null, 2));
    }
    // Throw error with full details in message so it's visible even if console.error doesn't work
    const errorMsg = postError.response 
      ? `POST failed (${postError.response.status}): ${JSON.stringify(postError.response.data)}`
      : `POST failed: ${postError.message}`;
    throw new Error(errorMsg);
  }

} catch (error) {
  console.error('❌ Supabase upsert error:', error.message);
  if (error.response) {
    console.error('Response status:', error.response.status);
    console.error('Response headers:', JSON.stringify(error.response.headers, null, 2));
    console.error('Response data:', JSON.stringify(error.response.data, null, 2));
    console.error('Request body that failed:', JSON.stringify(body, null, 2));
    throw new Error(`Supabase error (${error.response.status}): ${JSON.stringify(error.response.data)}`);
  }
  throw error;
}

// Create binary 'data' from JSON manifest (S3 node expects 'data' field)
// Pass through manifest, r2Key, orderId, and _config for downstream nodes
const input = $input.first().json || {};
const { manifest, orderId, _config } = input;

// Fallback key if upstream ever omits r2Key
const r2Key = input.r2Key 
  || `book-mvp-simple-adventure/orders/${orderId}/manifests/1-manifest.json`;

const data = Buffer.from(JSON.stringify(manifest), 'utf8');

return [{
  json: { r2Key, orderId, manifest, _config }, // Pass through for Supabase node
  binary: {
    data: {
      data,
      mimeType: 'application/json',
      fileName: '1-manifest.json'
    }
  }
}];
